-- Supabase Swipe Dummy Data (June 1 - August 31, 2025 & 2026)
-- 10 Employees, 2 per shift, realistic swipe timings
-- Drop invalid triggers attached to swipe table:
DROP TRIGGER IF EXISTS trg_check_middle_gap ON public.swipe;
DROP TRIGGER IF EXISTS check_gap_trigger ON public.swipe;
DROP TRIGGER IF EXISTS detect_swipe_gap ON public.swipe;
DROP TRIGGER IF EXISTS trg_check_swipe_gaps ON public.swipe;
DELETE FROM public.approval_requests WHERE reason = 'Swipe gap > 30 minutes';

